		var passive_draw := 0 if draw_basis <= 2 else (1 if draw_basis <= 4 else 2)
		if policy == "SeasonBoundedRhythm": passive_draw = 0 if core_count < 2 else mini(passive_draw, cards.size() - 1)
		immediate_draw += passive_draw
