	if id.is_empty(): return
	for index in range(owned.size()):
		if str(owned[index].get("cardId", "")) == id:
			owned[index] = card
			if _owned_index_ready: _owned_by_id[id] = card
			return
	owned.append(card)
	if _owned_index_ready: _owned_by_id[id] = card

