	var gear: Dictionary = EquipmentDetails.equipment(item)
	if worn.is_empty(): worn = _equipped_items()
	var current: Dictionary = {}
	for candidate in worn:
		if EquipmentDetails.equipment(candidate).get("slot", "") == gear.get("slot", ""):
			current = candidate
			break
	return current

