	ui.button(P.localized("refresh_relic"), Rect2(620, 236, 232, 53), func(): Game.command("relic.read", {"pile_id": pile_id}), not Game.allowed("relic.read"))
	if not fresh:
		ui.text(P.localized("relic_changed"), Rect2(115, 317, 730, 82), 27, P.MUTED)
