		var parts := raw_id.split("|", false)
		if parts.size() == 3:
			var quality := parts[0].capitalize()
			var element := parts[1].to_lower()
			var slot := parts[2].to_lower()
			var equipment_key := "Equipment/%s/%s_%s.png" % [quality, slot, element]
