		var segment_label: Label = ui.text(segment_text, Rect2(x, 48, segment_width, 34), 22, P.ELEMENT.get(segment.kind, Color.WHITE), panel, false)
		segment_label.autowrap_mode = TextServer.AUTOWRAP_OFF
