		else: panel.tooltip_text += "\n" + P.localized(parts_key) % [int(preview.get("shield_gain", 0)) + int(preview.get("shield_overflow", 0)), int(preview.get("shield_gain", 0)), int(preview.get("shield_overflow", 0))]

