before._process:
func _process(_delta: float) -> void:
	_check_login_timeout()
	_process_client_info()
	_check_shop_rotation()
	var now := Time.get_ticks_msec()
	var pending_changed := false
	if _combat_ready_at > 0 and now >= _combat_ready_at:
		_combat_ready_at = 0
		pending_changed = true
	if not _rejected_state_request.is_empty():
		if not _rejected_state_current(): _rejected_state_request = {}
		elif now >= int(_rejected_state_request.deadline):
			_recover_room_authority()
			pending_changed = true
	if room.has("extraction_remaining_ms"):
		if _extraction_sync_at == 0:
			_extraction_sync_at = now + 1000
		elif now >= _extraction_sync_at:
			_extraction_sync_at = now + 1000
			if _snapshot_request_pending and now - _snapshot_request_at > 3000: _snapshot_request_pending = false
			_request_snapshot()
	else:
		_extraction_sync_at = 0
	var phase: String = str(room.get("player", {}).get("phase", ""))
	if phase in ["Pve", "Pvp"]:
		if _combat_sync_at == 0: _combat_sync_at = now + 4000
		elif now >= _combat_sync_at:
			_combat_sync_at = now + 4000
			# Natural draws and utility intents may have no presentation event.
			# Keep the visible hand and legal opportunities authoritative.
			if _snapshot_request_pending and now - _snapshot_request_at > 3000: _snapshot_request_pending = false
			_request_snapshot()
	else: _combat_sync_at = 0
	if settlement.is_empty() and (phase in ["Extracted", "Dead"] or _room_actions_closed() or not _settlement_recovery_match_id.is_empty()) and now >= _settlement_poll_at and not _settlement_polling:
		_poll_ready_settlement()
	if not _pending_play.is_empty() and Time.get_ticks_msec() > _play_deadline:
		_pending_play = {}
		pending_changed = true
	for request_id in _pending_commands.keys():
		if Time.get_ticks_msec() > int(_pending_commands[request_id].get("deadline", 0)):
			var expired: Dictionary = _pending_commands[request_id]
			var timeout := {"type":"command_lifecycle", "event_type":"command.state_timeout" if expired.get("confirmed", false) else "command.timeout",
				"request_id":request_id, "action":expired.get("action", ""), "result":"state_timeout" if expired.get("confirmed", false) else "timeout",
				"execution_outcome":"confirmed_state_missing" if expired.get("confirmed", false) else "unknown", "trace_only":true}
			timeout.merge(expired.get("origin_context", {}), false)
			_on_gateway_telemetry(timeout)
			if str(expired.get("room_id", "")) != str(room.get("room_id", "")) or int(expired.get("session_generation", -1)) != gateway.session_generation or int(expired.get("room_context_epoch", -1)) != _room_context_epoch:
				_pending_commands.erase(request_id)
				pending_changed = true
				continue
			# A missing reply does not prove that the write failed. Both an
			# unknown outcome and a confirmed write without its new state must
			# recover authority before another intent can use the stale room.
			# Never replay the ambiguous write under a new request identity.
			# Retain receipt ownership, but remove stale action data. A transport
			# connection marker alone cannot make the old room writable again.
			_recover_room_authority()
			pending_changed = true
			break
	if not _queued_command.is_empty() and Time.get_ticks_msec() > _queue_deadline:
		_queued_command = {}
		notice.emit(P.localized("request_not_sent"))
		pending_changed = true
	_flush_latest_commands()
	_flush_combat_preview()
	if pending_changed: changed.emit()

before._recover_room_authority:
func _recover_room_authority() -> void:
	_command_recovery_context = {"session_generation": gateway.session_generation, "room_context_epoch": _room_context_epoch,
		"room_id": str(room.get("room_id", "")), "match_id": _settlement_match_id()}
	_rejected_state_request = {}
	room = {}
	selected_cards.clear()
	clear_combat_preview()
	_pending_commands.clear()
	_pending_play = {}
	_latest_commands.clear()
	_queued_command = {}
	_snapshot_request_pending = false
	gateway.recovering = true
	gateway.connect_realtime()

before._check_shop_rotation:
func _check_shop_rotation() -> void:
	if gateway == null or gateway.token.is_empty() or lobby.is_empty(): return
	if Time.get_ticks_msec() < _shop_rotation_check_at: return
	_shop_rotation_check_at = Time.get_ticks_msec() + 60000
	var shop: Dictionary = lobby.shop if lobby.get("shop") is Dictionary else {}
	if shop.is_empty(): return
	# The server rotates the regular shop at 04:00 China time (20:00 UTC).
	var day: Dictionary = Time.get_datetime_dict_from_unix_time(int(Time.get_unix_time_from_system()) + 4 * 3600)
	var reset_key := "%04d-%02d-%02d" % [day.year, day.month, day.day]
	if str(shop.get("resetKey", "")) != reset_key: refresh_cache("shop")

before._process_client_info:
func _process_client_info() -> void:
	_client_info_socket.poll()
	if _client_info_socket.get_ready_state() == WebSocketPeer.STATE_OPEN:
		while _client_info_socket.get_available_packet_count() > 0:
			var message: Variant = JSON.parse_string(_client_info_socket.get_packet().get_string_from_utf8())
			if message is Dictionary:
				_apply_server_info(message)
	elif _client_info_socket.get_ready_state() == WebSocketPeer.STATE_CLOSED and Time.get_ticks_msec() >= _client_info_retry_at:
		_client_info_retry_at = Time.get_ticks_msec() + 5000
		var url: String = gateway.base_url.replace("https://", "wss://").replace("http://", "ws://")
		_client_info_socket = WebSocketPeer.new()
		_client_info_socket.connect_to_url(url + "/ws/v1/client-info")

before._apply_server_info:
func _apply_server_info(info: Dictionary) -> void:
	if info == server_info: return
	server_info = info
	if lobby.is_empty():
		changed.emit()
	else:
		validate_config(str(info.get("configVersion", "")), "server")

before._login:
func _login(address: String, display_name: String, steam_login: bool) -> void:
	if busy: return
	display_name = display_name.strip_edges()
	if not steam_login and display_name.is_empty():
		_reject_login(P.localized("enter_account"))
		return
	address = address.strip_edges().trim_suffix("/")
	if not (address.begins_with("http://") or address.begins_with("https://")):
		_reject_login(P.localized("invalid_server_url"))
		return
	if not OS.is_debug_build() and not address.begins_with("https://"):
		_reject_login(P.localized("https_required"))
		return
	if not steam_login and not platform.local_login_enabled():
		_reject_login(P.localized("local_login_dev_only"))
		return
	if steam_login:
		var unavailable: String = platform.login_unavailable_reason()
		if not unavailable.is_empty():
			authentication_reason = unavailable
			notice.emit(unavailable)
			changed.emit()
			return
	_clear_authenticated_state()
	authentication_reason = ""
	configuration_error = ""
	gateway.begin_sign_in(address)
	var generation: int = gateway.session_generation
	busy = true
	_login_generation = generation
	_login_deadline = Time.get_ticks_msec() + LOGIN_TIMEOUT_MS
	connection = P.localized("connecting")
	changed.emit()
	var has_current_server_info: bool = not server_info.is_empty() and _server_info_address == gateway.base_url
	var server_ready: bool = (has_current_server_info and validate_config(str(server_info.get("configVersion", "")), "server")) or await _refresh_server_info()
	if generation != gateway.session_generation: return
	if server_ready:
		var capability := "identity.steam" if steam_login else "identity.local"
		if capability not in server_info.get("capabilities", []):
			authentication_reason = P.localized("steam_disabled") if steam_login else P.localized("local_login_disabled")
			notice.emit(authentication_reason)
		else:
			var sign_in: Dictionary = {"deviceId": gateway.device_id, "displayName": display_name}
			var ticket_result: Dictionary = {"ok": true}
			if steam_login:
				ticket_result = await platform.request_login_ticket()
				if ticket_result.ok: sign_in = {"ticket": ticket_result.ticket, "displayName": display_name}
			if generation != gateway.session_generation: return
			if ticket_result.ok:
				var result: Dictionary = await gateway.request("/api/v1/auth/steam" if steam_login else "/api/v1/auth/local", HTTPClient.METHOD_POST, sign_in)
				if generation != gateway.session_generation: return
				if steam_login: platform.release_ticket()
				if result.ok and result.data is Dictionary and result.data.get("player") is Dictionary:
					if gateway.accept_session(str(result.data.get("accessToken", "")), str(result.data.get("expiresAt", "")), str(result.data.get("player", {}).get("userId", ""))):
						if not steam_login: gateway.remember_local_account(str(result.data.get("player", {}).get("displayName", "")))
						await refresh_lobby()
						if generation != gateway.session_generation: return
						if not lobby.is_empty() and configuration_error.is_empty(): gateway.connect_realtime()
					else: gateway.end_session(P.localized("invalid_login_credential"))
			else:
				authentication_reason = ticket_result.error
				notice.emit(authentication_reason)
	if generation != gateway.session_generation: return
	_login_deadline = 0
	_login_generation = -1
	busy = false
	if lobby.is_empty():
		gateway.end_session("", false)
		connection = P.localized("disconnected")
	changed.emit()

before._refresh_server_info:
func _refresh_server_info() -> bool:
	var generation: int = gateway.session_generation
	var address: String = gateway.base_url
	var response: Dictionary = await gateway.request("/api/v1/client-info")
	if generation != gateway.session_generation or address != gateway.base_url: return false
	if not response.ok or not response.data is Dictionary: return false
	_apply_server_info(response.data)
	_server_info_address = gateway.base_url
	return validate_config(str(server_info.get("configVersion", "")), "server")

# Source labels use stable keys; translated display text can be ambiguous.

before.validate_config:
func validate_config(version: String, source: String) -> bool:
	if not version.is_empty() and version == str(CATALOG.data.version): return true
	if source == "room" and _room_catalogs.has(version) and _room_catalogs[version].get("_origin", "") == gateway.base_url: return true
	var source_argument: Variant = source
	var source_key := source
	if source_key in ["server", "hall", "room", "preparation"]:
		source_argument = {"translation_key": source_key}
	var version_argument: Variant = version if not version.is_empty() else {"translation_key": "version_missing"}
	configuration_error = P.message("config_mismatch_details", [source_argument, CATALOG.data.version, version_argument])
	gateway.end_session(configuration_error)
	return false

before.room_catalog_index:
func room_catalog_index() -> Dictionary:
	var version := str(room.get("config_version", ""))
	if room.is_empty() and settlement.get("season") is Dictionary: version = str(settlement.season.get("configVersion", ""))
	return _catalog_index_for_version(version)

before.read_historical_catalog:
func read_historical_catalog(version: String, expected_hash: String) -> Dictionary:
	# An archive is bound to its own published hash, including when its version
	# happens to equal the local package. Never interpret a missing old package
	# through the current lobby/room configuration.
	if version.is_empty() or version.length() > 80 or expected_hash.length() != 64: return {}
	var generation: int = gateway.session_generation
	var epoch := _catalog_request_epoch
	var address: String = gateway.base_url
	var response: Dictionary = await gateway.request("/api/v1/config/" + version.uri_encode(), HTTPClient.METHOD_GET, null, [404])
	if generation != gateway.session_generation or epoch != _catalog_request_epoch or address != gateway.base_url or response.get("stale_session", false): return {}
	var envelope: Dictionary = response.data if response.get("data") is Dictionary else {}
	if not response.get("ok", false) or envelope.get("configVersion") != version or envelope.get("contentHash") != expected_hash or not envelope.get("bundle") is PackedByteArray: return {}
	var reader := ConfigBundle.new()
	var decoded: Dictionary = reader.decode(envelope.bundle, version, expected_hash)
	if decoded.is_empty(): return {}
	var index: Dictionary = CatalogIndex.from_data(decoded)
	if index.get("version") != version or index.get("content_hash") != expected_hash: return {}
	return index

before._catalog_index_for_version:
func _catalog_index_for_version(version: String, required: bool = false) -> Dictionary:
	if version == str(CATALOG.data.version) or (version.is_empty() and not required): return {}
	var index: Dictionary = _room_catalogs.get(version, {})
	if not index.is_empty() and index.get("_origin", "") == gateway.base_url: return index
	# A missing archive is explicit; index readers must not silently select the built-in catalog.
	return {"version": version, "cards": {}, "levels": {}, "qualities": {}, "tables": {}}

before.preparation_catalog_index:
func preparation_catalog_index() -> Dictionary:
	if not preparation.is_empty():
		var snapshot: Dictionary = preparation.snapshot if preparation.get("snapshot") is Dictionary else {}
		return _catalog_index_for_version(str(snapshot.get("configVersion", "")), true)
	if season_preparation_active():
		return _catalog_index_for_version(str(lobby.season.get("configVersion", "")), true)
	return {}

before.preparation_catalog_ready:
func preparation_catalog_ready() -> bool:
	var index := preparation_catalog_index()
	if CatalogIndex.cards(index).is_empty() or PreparationModel.backpack("Free", index).is_empty(): return false
	var snapshot: Dictionary = preparation.snapshot if preparation.get("snapshot") is Dictionary else {}
	if snapshot.get("season") is Dictionary:
		if snapshot.season.get("configVersion") != snapshot.get("configVersion") or snapshot.season.get("difficultyId") != snapshot.get("difficulty"): return false
		return not PreparationModel.difficulty(int(str(snapshot.difficulty).trim_prefix("D")), index).is_empty()
	if snapshot.is_empty() and season_preparation_active():
		return not PreparationModel.difficulty(clampi(preparation_difficulty, 0, season_preparation_cap()), index).is_empty()
	return true

before.preparation_deck_preview:
func preparation_deck_preview() -> Dictionary:
	var snapshot: Dictionary = preparation.snapshot if preparation.get("snapshot") is Dictionary else {}
	if not preparation_catalog_ready(): return {}
	if not snapshot.is_empty():
		if not snapshot.get("cardIds") is Array or snapshot.cardIds.size() != 20: return {}
		if snapshot.get("season") is Dictionary and not snapshot.get("cardLevels") is Array: return {}
		if snapshot.get("cardLevels") is Array and snapshot.cardLevels.size() != 20: return {}
		for id in snapshot.cardIds:
			if CatalogIndex.card(str(id), preparation_catalog_index()).is_empty(): return {}
		var from_loan: bool = snapshot.get("borrowedTemplateId") is String and not snapshot.borrowedTemplateId.is_empty()
		return {"card_ids": snapshot.get("cardIds", []), "levels": snapshot.cardLevels if snapshot.get("cardLevels") is Array else [], "actual_levels": snapshot.actualCardLevels if snapshot.get("actualCardLevels") is Array else [], "borrowed": from_loan}
	if not preparation.is_empty(): return {}
	var index := preparation_catalog_index()
	var ids: Array = []
	var levels: Array[int] = []
	var actual: Array[int] = []
	var cap: int = clampi(preparation_difficulty, 0, season_preparation_cap()) if season_preparation_active() else 5
	var borrowed: bool = season_preparation_active() and use_borrowed_deck
	if borrowed:
		var loan := PreparationModel.borrowed_deck(hero_class, index)
		if loan.is_empty(): return {}
		ids = loan.card_ids
		for id in ids: levels.append(cap)
	else:
		ids = deck().get("cardIds", [])
		for id in ids:
			var found := false
			for owned in lobby.get("cards", []):
				if owned.get("cardId") != id: continue
				actual.append(int(owned.get("level", 0)))
				levels.append(mini(actual[-1], cap))
				found = true
				break
			if not found: return {}
	if ids.size() != 20: return {}
	for id in ids:
		if CatalogIndex.card(str(id), index).is_empty(): return {}
	return {"card_ids": ids.duplicate(), "levels": levels, "actual_levels": actual, "borrowed": borrowed}

before.preparation_preview_snapshot:
func preparation_preview_snapshot(tier: String) -> Dictionary:
	if preparation.get("snapshot") is Dictionary: return preparation.snapshot.duplicate(true)
	if not preparation.is_empty(): return {}
	var result := {"heroClass": hero_class, "maximumHp": P.CLASSES[hero_class][2], "equipmentIds": loadout().get("equipmentIds", []).duplicate(), "equipmentSnapshots": []}
	var items: Array = []
	for item in lobby.get("inventory", {}).get("equipments", []):
		if item.get("instanceId") in result.equipmentIds: items.append(item)
	var cap: int = clampi(preparation_difficulty, 0, season_preparation_cap()) if season_preparation_active() else 5
	result.equipmentSnapshots = items.duplicate(true)
	for weapon in lobby.get("classWeapons", []):
		if weapon.get("heroClass") == hero_class:
			result["actualClassWeaponLevel"] = int(weapon.level)
			result["classWeaponLevel"] = cap if season_preparation_active() and use_borrowed_deck else mini(int(weapon.level), cap)
	if season_preparation_active() and use_borrowed_deck: result["classWeaponLevel"] = cap
	var bag: Dictionary = PreparationModel.backpack(tier, preparation_catalog_index())
	if not bag.is_empty():
		result["backpackTier"] = tier
		result["backpackCapacity"] = bag.capacity
		result["safeSlotIndexes"] = bag.safe_indexes
	return result

before._ensure_room_catalog:
func _ensure_room_catalog(version: String) -> bool:
	if version == str(CATALOG.data.version): return true
	if version.is_empty() or version.length() > 80: return false
	var generation: int = gateway.session_generation
	var catalog_epoch: int = _catalog_request_epoch
	var address: String = gateway.base_url
	if _room_catalogs.has(version) and _room_catalogs[version].get("_origin", "") == address: return true
	var response: Dictionary = await gateway.request("/api/v1/config/" + version.uri_encode(), HTTPClient.METHOD_GET, null, [404])
	if generation != gateway.session_generation or catalog_epoch != _catalog_request_epoch or address != gateway.base_url: return false
	if not response.ok or not response.data is Dictionary: return false
	var envelope: Dictionary = response.data
	if str(envelope.get("configVersion", "")) != version or not envelope.get("bundle") is PackedByteArray: return false
	var reader := ConfigBundle.new()
	var decoded: Dictionary = reader.decode(envelope.bundle, version, str(envelope.get("contentHash", "")))
	if decoded.is_empty(): return false
	var index: Dictionary = CatalogIndex.from_data(decoded)
	if index.is_empty(): return false
	var retained: Dictionary = _room_catalogs.get(version, {})
	if not retained.is_empty() and retained.get("_origin", "") == address:
		return str(retained.get("content_hash", "")) == str(index.get("content_hash", ""))
	index["_origin"] = address
	_room_catalogs[version] = index
	return true

before._bootstrap_catalog_versions:
func _bootstrap_catalog_versions(snapshot: Dictionary) -> Array[String]:
	var versions: Array[String] = []
	var unfinished: Variant = snapshot.get("unfinishedMatch")
	if unfinished is Dictionary:
		var version := str(unfinished.get("configVersion", ""))
		if not version.is_empty(): versions.append(version)
	var receipt: Variant = snapshot.get("unfinishedSettlement")
	if receipt is Dictionary and receipt.get("season") is Dictionary:
		var version := str(receipt.season.get("configVersion", ""))
		if not version.is_empty() and version not in versions: versions.append(version)
	return versions

before._preparation_catalog_versions:
func _preparation_catalog_versions(snapshot: Dictionary) -> Array[String]:
	var versions: Array[String] = []
	var active: Variant = snapshot.get("activePreparation")
	if active is Dictionary:
		var saved: Dictionary = active.snapshot if active.get("snapshot") is Dictionary else {}
		versions.append(str(saved.get("configVersion", "")))
	var season: Variant = snapshot.get("season")
	if season is Dictionary and season.get("state") == "Active":
		var version: String = str(season.get("configVersion", ""))
		if version not in versions: versions.append(version)
	return versions

before.refresh_lobby:
func refresh_lobby() -> void:
	var generation: int = gateway.session_generation
	_lobby_request_epoch += 1
	var request_epoch := _lobby_request_epoch
	var origin_scope := _lobby_scope()
	var result: Dictionary = await gateway.request("/api/v1/bootstrap")
	if not _lobby_request_current(generation, request_epoch, origin_scope): return
	if not result.ok: return
	if not result.data is Dictionary or not validate_config(str(result.data.get("configVersion", "")), "hall"): return
	for required in ["player", "wallet", "materials"]:
		if not result.data.get(required) is Dictionary:
			notice.emit(P.localized("incomplete_lobby_data"))
			return
	if generation != gateway.session_generation: return
	var next_lobby: Dictionary = result.data.duplicate(true)
	# Decorations are account data. An unavailable original response never
	# supplies another account's cached ownership or a made-up selection.
	var cosmetic_result: Dictionary = await gateway.request("/api/v1/cosmetics", HTTPClient.METHOD_GET, null, [404])
	if not _lobby_request_current(generation, request_epoch, origin_scope): return
	next_lobby["cosmetics"] = cosmetic_result.data if cosmetic_result.get("ok", false) and cosmetic_result.get("data") is Dictionary and JourneyRewardModel.valid_inventory(cosmetic_result.data) else {}
	if _settlement_ack_pending_id != "":
		next_lobby["unfinishedSettlement"] = null
		next_lobby["unfinishedMatch"] = null
	if not next_lobby.get("mail") is Dictionary:
		var mail_result: Dictionary = await gateway.request("/api/v1/mail", HTTPClient.METHOD_GET, null, [404])
		if not _lobby_request_current(generation, request_epoch, origin_scope): return
		next_lobby["mail"] = mail_result.data if mail_result.ok and mail_result.data is Dictionary else {"items": [], "unreadCount": 0}
	# Older servers omit the optional account snapshot fields. Fetch those only
	# once during login/recovery, never when a module is opened.
	if not next_lobby.get("shop") is Dictionary or not next_lobby.get("market") is Array or not next_lobby.get("inventory") is Dictionary:
		var economy: Dictionary = await gateway.request("/api/v1/economy/context")
		if not _lobby_request_current(generation, request_epoch, origin_scope): return
		if economy.ok and economy.data is Dictionary:
			next_lobby["shop"] = economy.data.get("shop", {})
			next_lobby["market"] = economy.data.get("market", [])
			next_lobby["inventory"] = economy.data.get("inventory", {})
	if next_lobby.get("unfinishedSettlement") == null and next_lobby.get("unfinishedMatch") == null and room.is_empty() and ticket.is_empty() and not next_lobby.has("activePreparation"):
		var active: Dictionary = await gateway.request("/api/v1/preparations", HTTPClient.METHOD_GET, null, [404])
		if not _lobby_request_current(generation, request_epoch, origin_scope): return
		if active.ok:
			if not active.data is Dictionary: return
			next_lobby["activePreparation"] = active.data
		elif active.status == 404: next_lobby["activePreparation"] = null
	if not _lobby_request_current(generation, request_epoch, origin_scope): return
	for version in _bootstrap_catalog_versions(next_lobby):
		var loaded: bool = await _ensure_room_catalog(version)
		if not _lobby_request_current(generation, request_epoch, origin_scope): return
		if not loaded:
			configuration_error = P.message("config_archive_unavailable", [])
			gateway.end_session(configuration_error)
			return
	var preparation_ready := true
	for version in _preparation_catalog_versions(next_lobby):
		var loaded: bool = await _ensure_room_catalog(version)
		if not _lobby_request_current(generation, request_epoch, origin_scope): return
		preparation_ready = preparation_ready and loaded
	preparation_configuration_error = "" if preparation_ready else P.message("config_archive_unavailable", [])
	lobby = next_lobby
	mail = lobby.get("mail", {"items": [], "unreadCount": 0})
	for module in ["shop", "market", "inventory", "cards", "decks", "wallet", "mail", "cosmetics"]:
		_cache_versions[module] = int(_cache_versions.get(module, 0)) + 1
	if lobby.player.get("selectedClass") != null: hero_class = lobby.player.selectedClass
	if lobby.get("unfinishedSettlement") != null:
		gateway.room_id = ""
		gateway.room_revision = 0
		settlement = lobby.unfinishedSettlement
		_settlement_recovery_match_id = ""
	elif lobby.get("unfinishedMatch") != null:
		gateway.room_id = lobby.unfinishedMatch.roomId
	elif room.is_empty() and ticket.is_empty():
		gateway.room_id = ""
		gateway.room_revision = 0
		if lobby.has("activePreparation"):
			preparation = lobby.activePreparation if lobby.activePreparation is Dictionary else {}
	changed.emit()

before._lobby_scope:
func _lobby_scope() -> String:
	return JSON.stringify([gateway.base_url, room.get("match_id", ""), gateway.room_id, preparation.get("preparationId", ""),
		ticket.get("ticketId", ""), settlement.get("settlementId", ""), _settlement_ack_pending_id,
		_room_context_epoch, _settlement_recovery_match_id, _cache_versions])

before.update_cache:
func update_cache(module: String, value: Variant) -> void:
	if lobby.is_empty(): return
	if module == "mail" and value is Dictionary: mail = value
	lobby[module] = value
	_cache_versions[module] = int(_cache_versions.get(module, 0)) + 1
	cache_changed.emit(module)
	if module == "cards" and value is Array and lobby.get("shop") is Dictionary:
		var ownership: Dictionary = {}
		for card in value:
			if card is Dictionary: ownership[str(card.get("cardId", ""))] = bool(card.get("unlocked", false)) and int(card.get("copyCount", 0)) > 0
		var next_shop: Dictionary = lobby.shop.duplicate(true)
		var products: Array = next_shop.get("products", [])
		var changed_shop := false
		for index in products.size():
			var product: Dictionary = products[index]
			if str(product.get("kind", "")) != "Cards": continue
			var parsed: Variant = product.get("payload", {})
			if not parsed is Dictionary or not parsed.has("cardId"): continue
			var owned := bool(ownership.get(str(parsed.cardId), false))
			if bool(product.get("alreadyOwned", false)) == owned: continue
			product["alreadyOwned"] = owned
			products[index] = product
			changed_shop = true
		if changed_shop:
			next_shop["products"] = products
			lobby["shop"] = next_shop
			cache_changed.emit("shop")

before.refresh_cache:
func refresh_cache(module: String) -> void:
	if gateway.token.is_empty() or lobby.is_empty(): return
	if _cache_syncing.has(module):
		_cache_sync_again[module] = true
		return
	var paths := {"shop": "/api/v1/shop/", "market": "/api/v1/market/", "inventory": "/api/v1/inventory/", "cards": "/api/v1/cards/", "decks": "/api/v1/decks/", "mail": "/api/v1/mail/", "wallet": "/api/v1/economy/wallet", "cosmetics": "/api/v1/cosmetics"}
	if not paths.has(module): return
	var generation: int = gateway.session_generation
	var origin: String = str(gateway.base_url)
	var account: String = str(lobby.get("player", {}).get("userId", ""))
	_cache_syncing[module] = generation
	while generation == gateway.session_generation:
		_cache_sync_again.erase(module)
		var version: int = int(_cache_versions.get(module, 0))
		var result: Dictionary = await gateway.request(paths[module], HTTPClient.METHOD_GET, null, [404])
		if generation != gateway.session_generation or origin != str(gateway.base_url) or account != str(lobby.get("player", {}).get("userId", "")): break
		if int(_cache_versions.get(module, 0)) != version:
			_cache_sync_again[module] = true
		elif result.ok and (module != "cosmetics" or result.get("data") is Dictionary and JourneyRewardModel.valid_inventory(result.data)):
			update_cache(module, result.data)
		elif module == "mail" and int(result.get("status", 0)) == 404:
			update_cache("mail", {"items": [], "unreadCount": 0})
		if not _cache_sync_again.has(module): break
	if _cache_syncing.get(module) == generation:
		_cache_syncing.erase(module)
		_cache_sync_again.erase(module)

